import { useForm } from 'react-hook-form'
import { z } from 'zod'
import { zodResolver } from '@hookform/resolvers/zod'
import { Link } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { toast } from 'sonner'
import { supabaseAuthService } from '@/integrations/supabase/auth'

const schema = z.object({ email: z.string().email() })
type FormData = z.infer<typeof schema>

export function ForgotPasswordPage() {
  const { t } = useTranslation('auth')
  const { register, handleSubmit, formState: { isSubmitting } } = useForm<FormData>({ resolver: zodResolver(schema) })

  const onSubmit = async (data: FormData) => {
    try {
      await supabaseAuthService.sendPasswordResetEmail(data.email)
      toast.success('Reset link sent. Check your email.')
    } catch {
      toast.error('Failed to send reset link.')
    }
  }

  return (
    <div className="bg-surface rounded-2xl border border-border p-8 shadow-sm">
      <h1 className="text-xl font-semibold mb-1">{t('forgotTitle')}</h1>
      <p className="text-sm text-muted-foreground mb-6">{t('forgotSubtitle')}</p>
      <form onSubmit={handleSubmit(onSubmit)} className="flex flex-col gap-4">
        <div>
          <label className="text-sm font-medium block mb-1.5">{t('email')}</label>
          <input {...register('email')} type="email" className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-accent" />
        </div>
        <button type="submit" disabled={isSubmitting} className="w-full bg-accent text-accent-foreground rounded-lg py-2.5 text-sm font-medium hover:opacity-90 disabled:opacity-50">
          {isSubmitting ? '...' : t('sendResetLink')}
        </button>
      </form>
      <p className="text-center text-xs text-muted-foreground mt-4">
        <Link to="/auth/login" className="text-accent hover:underline">{t('backToLogin')}</Link>
      </p>
    </div>
  )
}
